import numpy as np, pandas as pd
def sim(m,r,h,v0,ang,rho,Cd,g=9.81):
    k=0.5*rho*Cd*np.pi*r**2/m
    a=np.radians(ang);vx=v0*np.cos(a);vy=v0*np.sin(a)
    x=0;y=h;t=0;dt=0.002
    while y>0:
        v=np.hypot(vx,vy)
        vx+=-k*v*vx*dt; vy+=(-g-k*v*vy)*dt
        x+=vx*dt;y+=vy*dt;t+=dt
    return t,x,np.hypot(vx,vy)
